static void _yr_compiler_default_include_free(
    const char* callback_result_ptr,
    void* user_data)
{
  if(callback_result_ptr != NULL)
  {
    yr_free((void*)callback_result_ptr);
  }
}


const char* _yr_compiler_default_include_callback(
    const char* include_name,
    const char* calling_rule_filename,
    const char* calling_rule_namespace,
    void* user_data)
{
  #ifndef _MSC_VER
  struct stat stbuf;
  #endif

  #ifdef _MSC_VER
  char* b = NULL;
  #endif

  char* s = NULL;
  char* f;
  char* file_buffer;
  char buffer[1024];

  #ifdef _MSC_VER
  long file_size;
  #else
  off_t file_size;
  #endif

  int fd = -1;

  if (calling_rule_filename != NULL)
    strlcpy(buffer, calling_rule_filename, sizeof(buffer));
  else
    buffer[0] = '\0';

  s = strrchr(buffer, '/');

  #ifdef _MSC_VER
  b = strrchr(buffer, '\\'); // in Windows both path delimiters are accepted
  #endif

  #ifdef _MSC_VER
  if (s != NULL || b != NULL)
  #else
  if (s != NULL)
  #endif
  {
    #ifdef _MSC_VER
    f = (b > s) ? (b + 1) : (s + 1);
    #else
    f = s + 1;
    #endif

    strlcpy(f, include_name, sizeof(buffer) - (f - buffer));

    f = buffer;

    // SECURITY: Potential for directory traversal here.
    #ifdef _MSC_VER
    _sopen_s(&fd, f, _O_RDONLY, _SH_DENYRW, _S_IREAD);
    #else
    fd = open(f, O_RDONLY);
    #endif

    // if include file was not found relative to current source file,
    // try to open it with path as specified by user (maybe user wrote
    // a full path)
    if (fd == -1)
    {
      f = (char*) include_name;
    }
  }
  else
  {
    f = (char*) include_name;
  }

  if (fd == -1)
  {
    // SECURITY: Potential for directory traversal here.
    #ifdef _MSC_VER
    _sopen_s(&fd, f, _O_RDONLY, _SH_DENYRW, _S_IREAD);
    #else
    fd = open(f, O_RDONLY);
    #endif
  }

  if (fd == -1)
    return NULL;

  #ifdef _MSC_VER
  file_size = _filelength(fd);
  if (file_size == -1)
  {
    _close(fd);
    return NULL;
  }
  #else
  if ((fstat(fd, &stbuf) != 0) || (!S_ISREG(stbuf.st_mode)))
  {
    close(fd);
    return NULL;
  }
  file_size = stbuf.st_size;
  #endif

  file_buffer = (char*) yr_malloc(file_size + 1);

  if (file_buffer == NULL)
  {
    #ifdef _MSC_VER
    _close(fd);
    #else
    close(fd);
    #endif

    return NULL;
  }

  if (file_size != read(fd, file_buffer, file_size))
  {
    yr_free(file_buffer);

    #ifdef _MSC_VER
    _close(fd);
    #else
    close(fd);
    #endif

    return NULL;
  }
  else
  {
    file_buffer[file_size] = '\0';
  }

  #ifdef _MSC_VER
  _close(fd);
  #else
  close(fd);
  #endif

  return file_buffer;
}


