extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
{
  YR_RULES* rules;
  YR_COMPILER* compiler;

  char* buffer = (char*) malloc(size + 1);

  if (!buffer)
    return 1;

  strncpy(buffer, (const char *) data, size);
  buffer[size] = 0;

  if (yr_compiler_create(&compiler) != ERROR_SUCCESS)
  {
    free(buffer);
    return 1;
  }

